CREATE TABLE IF NOT EXISTS schema_migrations(version text primary key,applied_at timestamptz default now());
CREATE TABLE IF NOT EXISTS users(id bigserial primary key,email text unique not null,password_hash text not null,name text,created_at timestamptz default now());
ALTER TABLE users ADD COLUMN IF NOT EXISTS email_verified_at timestamptz;
CREATE TABLE IF NOT EXISTS sessions(id bigserial primary key,user_id bigint references users(id) on delete cascade,token_hash text unique not null,expires_at timestamptz not null,created_at timestamptz default now());
CREATE TABLE IF NOT EXISTS addresses(id bigserial primary key,user_id bigint references users(id) on delete cascade,label text,name text,line1 text,line2 text,city text,state text,postal_code text,country text default 'US',phone text,created_at timestamptz default now());
CREATE TABLE IF NOT EXISTS wishlists(user_id bigint references users(id) on delete cascade,product_id text not null,created_at timestamptz default now(),primary key(user_id,product_id));
CREATE TABLE IF NOT EXISTS carts(user_id bigint references users(id) on delete cascade,product_id text not null,variant_id text not null default '',quantity integer not null check(quantity between 1 and 10),updated_at timestamptz default now(),primary key(user_id,product_id,variant_id));
CREATE TABLE IF NOT EXISTS customers(id bigserial primary key,email text unique not null,name text,created_at timestamptz default now());
CREATE TABLE IF NOT EXISTS orders(id bigserial primary key,order_number text unique not null,stripe_session_id text unique not null,customer_email text not null,status text not null default 'paid',fulfillment_status text not null default 'pending',currency text not null default 'usd',total_cents integer not null default 0,cj_order_id text,tracking_number text,carrier text,shipping_json jsonb,created_at timestamptz default now(),updated_at timestamptz default now());
ALTER TABLE orders ADD COLUMN IF NOT EXISTS tracking_url text;
CREATE TABLE IF NOT EXISTS returns(id bigserial primary key,order_id bigint references orders(id) on delete cascade,email text not null,reason text not null,details text,status text default 'requested',refund_cents integer default 0,created_at timestamptz default now(),updated_at timestamptz default now());
CREATE TABLE IF NOT EXISTS order_items(id bigserial primary key,order_id bigint references orders(id) on delete cascade,product_id text,variant_id text,sku text,name text,quantity integer,unit_amount integer,image text);
CREATE TABLE IF NOT EXISTS reviews(id bigserial primary key,product_id text not null,email text not null,rating integer not null check(rating between 1 and 5),title text,body text,verified boolean default false,status text default 'pending',created_at timestamptz default now());
ALTER TABLE reviews ADD COLUMN IF NOT EXISTS media_urls jsonb NOT NULL DEFAULT '[]'::jsonb;
CREATE TABLE IF NOT EXISTS promotions(id bigserial primary key,code text unique not null,kind text not null,value integer not null,min_cents integer default 0,active boolean default true,starts_at timestamptz,ends_at timestamptz,max_uses integer,uses integer default 0);
ALTER TABLE promotions ADD COLUMN IF NOT EXISTS created_at timestamptz default now();
CREATE TABLE IF NOT EXISTS order_events(id bigserial primary key,order_id bigint references orders(id) on delete cascade,event_type text not null,detail_json jsonb,created_at timestamptz default now());
CREATE TABLE IF NOT EXISTS support_tickets(id bigserial primary key,email text not null,order_number text,category text,message text,status text default 'open',created_at timestamptz default now(),updated_at timestamptz default now());
CREATE TABLE IF NOT EXISTS support_messages(id bigserial primary key,ticket_id bigint references support_tickets(id) on delete cascade,sender text not null check(sender in ('customer','staff')),message text not null,created_at timestamptz default now());
CREATE TABLE IF NOT EXISTS email_verifications(id bigserial primary key,user_id bigint references users(id) on delete cascade,token_hash text unique not null,expires_at timestamptz not null,used_at timestamptz,created_at timestamptz default now());
CREATE TABLE IF NOT EXISTS password_resets(id bigserial primary key,user_id bigint references users(id) on delete cascade,token_hash text unique not null,expires_at timestamptz not null,used_at timestamptz,created_at timestamptz default now());
CREATE TABLE IF NOT EXISTS notification_subscriptions(id bigserial primary key,user_id bigint references users(id) on delete cascade,email text not null,product_id text,kind text not null check(kind in ('back_in_stock','price_drop','marketing')),target_price_cents integer,active boolean default true,created_at timestamptz default now(),unique(email,product_id,kind));
CREATE TABLE IF NOT EXISTS catalog_snapshots(product_id text not null,variant_id text not null default '',name text,price_cents integer,available boolean default true,stock integer,image text,checked_at timestamptz default now(),primary key(product_id,variant_id));
ALTER TABLE catalog_snapshots ADD COLUMN IF NOT EXISTS category text;
CREATE TABLE IF NOT EXISTS analytics_events(id bigserial primary key,user_id bigint references users(id) on delete set null,session_key text,event_name text not null,product_id text,metadata jsonb,created_at timestamptz default now());
CREATE TABLE IF NOT EXISTS staff_users(id bigserial primary key,email text unique not null,role text not null default 'support',active boolean default true,created_at timestamptz default now());
CREATE TABLE IF NOT EXISTS user_rewards(user_id bigint primary key references users(id) on delete cascade,points_balance integer not null default 0,store_credit_cents integer not null default 0,referral_code text unique not null,referred_by_user_id bigint references users(id) on delete set null,updated_at timestamptz default now());
CREATE TABLE IF NOT EXISTS reward_ledger(id bigserial primary key,user_id bigint references users(id) on delete cascade,order_id bigint references orders(id) on delete set null,kind text not null,points_delta integer not null default 0,credit_cents_delta integer not null default 0,note text,created_at timestamptz default now());
CREATE TABLE IF NOT EXISTS notification_deliveries(id bigserial primary key,subscription_id bigint references notification_subscriptions(id) on delete cascade,trigger_key text not null,sent_at timestamptz default now(),unique(subscription_id,trigger_key));
CREATE TABLE IF NOT EXISTS product_questions(id bigserial primary key,product_id text not null,user_id bigint references users(id) on delete set null,email text not null,question text not null,answer text,status text not null default 'pending',created_at timestamptz default now(),answered_at timestamptz);
CREATE UNIQUE INDEX IF NOT EXISTS reward_order_kind_unique ON reward_ledger(user_id,order_id,kind) WHERE order_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS orders_email_idx ON orders(lower(customer_email));
CREATE INDEX IF NOT EXISTS order_events_order_idx ON order_events(order_id,created_at desc);
CREATE INDEX IF NOT EXISTS reviews_product_idx ON reviews(product_id,status);
CREATE INDEX IF NOT EXISTS analytics_event_idx ON analytics_events(event_name,created_at desc);
CREATE INDEX IF NOT EXISTS notification_product_idx ON notification_subscriptions(product_id,kind,active);
CREATE UNIQUE INDEX IF NOT EXISTS notification_marketing_email_unique ON notification_subscriptions(lower(email),kind) WHERE product_id IS NULL AND kind='marketing';
CREATE INDEX IF NOT EXISTS catalog_checked_idx ON catalog_snapshots(checked_at desc);
CREATE INDEX IF NOT EXISTS questions_product_idx ON product_questions(product_id,status,created_at desc);
CREATE INDEX IF NOT EXISTS reward_ledger_user_idx ON reward_ledger(user_id,created_at desc);
CREATE INDEX IF NOT EXISTS support_messages_ticket_idx ON support_messages(ticket_id,created_at);
CREATE INDEX IF NOT EXISTS carts_updated_idx ON carts(updated_at desc);
CREATE TABLE IF NOT EXISTS store_credit_reservations(id bigserial primary key,user_id bigint references users(id) on delete cascade,amount_cents integer not null check(amount_cents>0),stripe_session_id text unique not null,status text not null default 'reserved' check(status in ('reserved','consumed','released')),expires_at timestamptz not null,created_at timestamptz default now());
CREATE TABLE IF NOT EXISTS lifecycle_deliveries(id bigserial primary key,user_id bigint references users(id) on delete cascade,kind text not null,dedupe_key text not null,sent_at timestamptz default now(),unique(user_id,kind,dedupe_key));
CREATE INDEX IF NOT EXISTS credit_reservations_user_idx ON store_credit_reservations(user_id,status,expires_at);
CREATE INDEX IF NOT EXISTS lifecycle_user_idx ON lifecycle_deliveries(user_id,kind,sent_at desc);
ALTER TABLE catalog_snapshots ADD COLUMN IF NOT EXISTS category text;
